import struct
import json

def is_perfect_square(n):
    root = int(np.sqrt(n))
    return n == root * root

def is_power_of_n(n, base=2):
    if n < 1:
        return False
    while n % base == 0:
        n //= base
    return n == 1

def find_largest_math_representation(n):
    if is_perfect_square(n):
        root = int(np.sqrt(n))
        return ("square", root)

    for base in range(2, 10):  # Checking for powers from 2 to 9
        exponent = 1
        while base ** exponent <= n:
            if base ** exponent == n:
                return ("power", base, exponent)
            exponent += 1

    return ("raw", n)  # If no representation found, store as raw

def compress_binary(file_path, output_path):
    with open(file_path, "rb") as f:
        binary_data = f.read()

    num_array = np.frombuffer(binary_data, dtype=np.uint32)
    compressed_data = [find_largest_math_representation(num) for num in num_array]

    with open(output_path, "w") as f:
        json.dump(compressed_data, f)

    print(f"Compression complete. Data saved to {output_path}")

def decompress_binary(input_path, output_path):
    with open(input_path, "r") as f:
        compressed_data = json.load(f)

    reconstructed_data = []
    for entry in compressed_data:
