        elif entry[0] == "power":
            reconstructed_data.append(entry[1] ** entry[2])
        else:
            reconstructed_data.append(entry[1])

    binary_output = np.array(reconstructed_data, dtype=np.uint32).tobytes()
    with open(output_path, "wb") as f:
        f.write(binary_output)

    print(f"Decompression complete. Data restored to {output_path}")

